// Parse Claude's delimited response — tolerant; reconstructs SIGNAL_DATA if missing
const response = $input.first().json;
const textBlocks = (response.content || []).filter(c => c.type === 'text');
const fullText = textBlocks.map(b => b.text).join('\n');

// BRIEF_DATA is mandatory — PDF cannot build without it
const briefMatch = fullText.match(/<BRIEF_DATA>([\s\S]*?)<\/BRIEF_DATA>/);
if (!briefMatch) {
  throw new Error('BRIEF_DATA block not found — Write Brief output malformed or truncated. Raw: ' + fullText.slice(0, 600));
}
let briefData;
try {
  briefData = JSON.parse(briefMatch[1].trim());
} catch (e) {
  throw new Error('BRIEF_DATA found but invalid JSON (likely truncated). Raw: ' + briefMatch[1].slice(0, 600));
}

// SIGNAL_DATA preferred but recoverable
let signal = null;
const signalMatch = fullText.match(/<SIGNAL_DATA>([\s\S]*?)<\/SIGNAL_DATA>/);
if (signalMatch) {
  try { signal = JSON.parse(signalMatch[1].trim()); } catch (e) { signal = null; }
}
if (!signal) {
  signal = {
    signal_date: briefData.footer_date || new Date().toISOString().slice(0, 10),
    top_signal: {
      company: briefData.company,
      score: briefData.score,
      tier: briefData.timing_label,
      person: briefData.decision_maker_name,
      role: briefData.decision_maker_role,
      action: briefData.horizon_label,
      horizon_weeks: briefData.horizon_label,
      source_url: ""
    },
    signals_log: []
  };
}

return [{
  json: {
    ...briefData,
    signal_date: signal.signal_date,
    top_signal: signal.top_signal,
    signals_log: signal.signals_log
  }
}];

