// =============================================================================
// Parse Signal Data — Phase 2.1.9b (parser hardening)
// PASTE THIS ENTIRE BLOCK into the n8n Parse Signal Data Code node, replacing
// existing code.
//
// Changes from v2.1.9 (marked >>> v2.1.9b):
//   (1) Parser now uses bracket-depth-balanced scanning instead of
//       firstBracket-to-lastBracket extraction. Tolerates preamble narration
//       containing stray "[" characters (e.g., "I'll search [F1, FE]...").
//   (2) Parser tries each balanced array region and prefers the one whose
//       first element has a `company` field. Falls back to any parseable
//       object array.
//   (3) Better error messages — shows the LAST 800 chars of raw input so
//       truncation cases are visible (was first 800, which missed the end).
//
// FE rotation logic (from v2.1.9) is unchanged:
//   FE_FORCE_DAYS = [2, 5, 6] = Tue/Fri/Sat. Edit this one line to change.
// =============================================================================

// ---- 1440 array parser + deterministic filter + picker (with revisit fallback) ----
const response = $input.first().json;
const textBlocks = (response.content || []).filter(c => c.type === 'text');
if (textBlocks.length === 0) {
  throw new Error('Run Signals returned no text content. Raw: ' + JSON.stringify(response).slice(0, 500));
}
let raw = textBlocks.map(b => b.text).join('\n').trim();

// >>> v2.1.9b: bracket-depth-balanced scan. Collects every balanced [...] region,
// then tries each (largest first), preferring ones whose first element has `company`.
const arrayCandidates = [];
{
  let depth = 0, start = -1;
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i];
    if (c === '[') {
      if (depth === 0) start = i;
      depth++;
    } else if (c === ']') {
      depth--;
      if (depth === 0 && start !== -1) {
        arrayCandidates.push(raw.substring(start, i + 1));
        start = -1;
      } else if (depth < 0) {
        depth = 0; // recover from mismatched closing bracket in narration
      }
    }
  }
}
if (arrayCandidates.length === 0) {
  throw new Error('No bracket-balanced array found in Run Signals output. Likely truncated - raise max_tokens. Raw (last 800): ' + raw.slice(-800));
}

let candidates = null;
let lastParseError = null;
arrayCandidates.sort((a, b) => b.length - a.length); // largest first
for (const cand of arrayCandidates) {
  try {
    const parsed = JSON.parse(cand);
    if (Array.isArray(parsed) && parsed.length > 0 && parsed[0] && typeof parsed[0] === 'object' && 'company' in parsed[0]) {
      candidates = parsed;
      break;
    }
    if (Array.isArray(parsed) && parsed.length > 0 && parsed[0] && typeof parsed[0] === 'object' && !candidates) {
      candidates = parsed; // fallback to any object array
    }
  } catch (e) {
    lastParseError = e.message;
    // Try with code fences stripped
    const stripped = cand.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    if (stripped !== cand) {
      try {
        const reparsed = JSON.parse(stripped);
        if (Array.isArray(reparsed) && reparsed.length > 0 && reparsed[0] && 'company' in reparsed[0]) {
          candidates = reparsed;
          break;
        }
      } catch (e2) { /* skip */ }
    }
  }
}
if (!candidates) {
  throw new Error('Bracket-balanced arrays found but none parseable as candidates. Last parse error: ' + lastParseError + '. Raw (last 800): ' + raw.slice(-800));
}
if (!Array.isArray(candidates) || candidates.length === 0) {
  throw new Error('Parsed value is not a non-empty array. Raw (last 800): ' + raw.slice(-800));
}

// HARD BLOCK = 1440 active deals + permanent suppressions. Never sent, period.
const HARD_BLOCK = [
  'Factory AI', 'JFrog', 'Mistral AI', 'Luminary Cloud', 'Netomi',
  'Shield AI', 'Wayve', 'Lattice', 'Omni Analytics', 'Legora',
  'Cerebras Systems', 'Sierra'
];

function normalise(name) {
  return (name || '').toLowerCase()
    .replace(/\b(inc|ltd|llc|corp|technologies|technology|ai|the)\b/g, '')
    .replace(/[^a-z0-9]/g, '').trim();
}
function isBlocked(companyNorm, listNorm) {
  return listNorm.some(function (b) {
    return b.length > 0 && (companyNorm === b ||
      companyNorm.indexOf(b) !== -1 || b.indexOf(companyNorm) !== -1);
  });
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.surfaced) staticData.surfaced = [];
const COOLING_DAYS = 30;
const now = Date.now();
staticData.surfaced = staticData.surfaced.filter(function (s) {
  return (now - s.ts) / 86400000 < COOLING_DAYS;
});
const hardBlockNorm = HARD_BLOCK.map(normalise);

// >>> v2.1.9: FE rotation. Force-FE days = Tue (2), Fri (5), Sat (6).
const FE_FORCE_DAYS = [2, 5, 6];
const todayDow = new Date().getUTCDay();
const forceFe = FE_FORCE_DAYS.indexOf(todayDow) >= 0;

const scanned = [];
let anyWinner = null;
let feWinner = null;
let revisitCandidate = null;

for (const c of candidates) {
  const nameNorm = normalise(c.company);
  const trigger = ((c.trigger_reason || (c.key_facts && c.key_facts.trigger) || '') + '').toLowerCase().trim();
  const hard = isBlocked(nameNorm, hardBlockNorm);
  const cooling = staticData.surfaced.some(function (s) { return s.name === nameNorm; });
  let status = 'eligible';
  if (hard) status = 'hard_blocked';
  else if (cooling) status = 'dedup_cooling';
  scanned.push({ company: c.company, score: c.score, status: status });
  if (status === 'eligible') {
    if (!anyWinner) anyWinner = c;
    const seriesUpper = (c.recommended_series || '').toUpperCase();
    if (forceFe && seriesUpper === 'FE' && !feWinner) feWinner = c;
  }
  if (!hard && !revisitCandidate) revisitCandidate = c;
}

let winner = (forceFe && feWinner) ? feWinner : anyWinner;
const feForceApplied = !!(forceFe && feWinner);
const feForceMissed = forceFe && !feWinner;

let revisitFlag = false;
if (!winner) {
  winner = revisitCandidate || candidates[0];
  revisitFlag = true;
}

const winnerNorm = normalise(winner.company);
const winnerTrig = ((winner.trigger_reason || (winner.key_facts && winner.key_facts.trigger) || '') + '').toLowerCase().trim();
const existingIdx = staticData.surfaced.findIndex(function (s) { return s.name === winnerNorm; });
if (existingIdx >= 0) staticData.surfaced[existingIdx].ts = now;
else staticData.surfaced.push({ name: winnerNorm, trigger: winnerTrig, display: winner.company, ts: now });

if (typeof staticData.lastBriefNumber !== 'number') staticData.lastBriefNumber = 9;
staticData.lastBriefNumber += 1;
winner.brief_number = String(staticData.lastBriefNumber).padStart(3, '0');

winner._revisit = revisitFlag;
winner._fe_force_applied = feForceApplied;
winner._fe_force_missed = feForceMissed;
winner._dow_utc = todayDow;
winner.scanned = scanned;
return [{ json: winner }];

// =============================================================================
// Audit Brief — Phase 2.1.8d
// PASTE THIS ENTIRE BLOCK into the n8n Code node body, replacing existing code.
// Changes from v2.1.8c (marked >>> v2.1.8d):
//   (1) Rule 2: added Unicode curly-quote alternatives — closes silent-failure
//       gap if writer ever emits typographic quotes directly
//   (2) Rule 6: vacancyRe expanded with "still seeking", "yet to sign/land/ink/secure",
//       "currently lacks", "remains without", "is unclaimed", "no current", "unclaimed"
//   (3) Rule 6: Pattern B now uses matchAll + min pairwise distance (was first-match-only)
//   (4) Rule 6: Patterns C and D now applied to deck (were p2-only)
//   (5) Rule 10: severity aligned to spec — critical when value_section true, medium when false
//       (was: critical only when value=on AND risks=3, else medium)
//   (6) Rule 11: budgets recalibrated 2500→2300 and 2300→2100 (Nourish 22 May overflowed
//       at ~2306 chars on old 2500 budget; tested against 5 real PDFs)
// =============================================================================

const src = $input.first().json;
const brief = src.brief_data || src;
const signal = src.signal_data || src._signal_data || {};
const retryCount = Number(src.retry_count || src._retry_count || 0);
const previousViolations = src._previous_violations || [];

const violations = [];
function add(rule, severity, detail) { violations.push({ rule: rule, severity: severity, detail: detail }); }
function wc(s) { return (s || '').replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length; }
function plainText(s) { return (s || '').replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim(); }

// Rule 1: Deal duration THREE/FOUR/FIVE YEARS
const dealPara = brief.deal_arch_para || '';
const dealPlain = plainText(dealPara);
if (/\bTWO\s+YEARS?\b/i.test(dealPlain)) add('min_3_year_deal', 'critical', 'deal_arch_para proposes TWO YEARS');
if (!/<font[^>]*>\s*(THREE|FOUR|FIVE) YEARS\s*<\/font>/i.test(dealPara)) add('missing_duration_marker', 'critical', 'deal_arch_para missing bold THREE/FOUR/FIVE YEARS marker');

// Rule 2: Opening quote
// >>> v2.1.8d: added Unicode curly-quote alternatives [\u201C\u201D]
const quote = (brief.opening_angle_quote || '').trim();
if (!/\?\s*(&rdquo;|"|[\u201C\u201D]|$)/.test(quote) || !/\b25 minutes\b/i.test(quote)) add('opening_quote_ending', 'critical', 'opening_angle_quote must contain "25 minutes" and end with "?"');
const quoteNoEnd = quote.replace(/25 minutes\?\s*(&rdquo;|"|[\u201C\u201D]|$).*$/, '');
if (/\b(the|those|these|spending|sitting out|wasting)\s+(fastest|hardest|toughest|best|most|same|next|last|whole|entire)?\s*25 minutes\b/i.test(quoteNoEnd)) add('opening_quote_metaphor', 'critical', '25 minutes used as metaphor');

// Rule 3: Opening intro declarative
const intro = (brief.opening_angle_intro || '').trim();
if (/\?\s*$/.test(intro)) add('opening_intro_question', 'critical', 'opening_angle_intro ends with "?" — must be declarative');

// Rule 4: footer_date matches today UTC
const todayD = new Date();
const monthsUC = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
const todayStr = todayD.getUTCDate() + ' ' + monthsUC[todayD.getUTCMonth()] + ' ' + todayD.getUTCFullYear();
if ((brief.footer_date || '').toUpperCase().trim() !== todayStr) add('footer_date_mismatch', 'medium', "footer_date '" + brief.footer_date + "' != today");

// Rule 5: industry_meta no trailing date
if (/[·\-\s]\s*\d{4}-\d{2}-\d{2}\s*$/.test(brief.industry_meta || '')) add('industry_meta_date_suffix', 'medium', 'industry_meta has trailing date');

// Rule 6: team-vacancy patterns in deck OR the_case_p2
const p2 = plainText(brief.the_case_p2 || '');
const deck = plainText(brief.deck || '');
const teamRaw = (brief.team_label || '').trim();
if (teamRaw) {
  const teamCap = teamRaw.split(/\s+/).map(function(w){ return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase(); }).join(' ');
  const teamUC = teamRaw.toUpperCase();
  const teamPattern = '(' + teamUC + '|' + teamCap + '|' + teamRaw + ')';

  // >>> v2.1.8d: vacancyRe expanded with additional natural-language phrasings.
  // Still excludes "slot is open" / "seat is open" by NOT including bare "is open"
  // (preserves the Datadog reference construction).
  const vacancyReSrc = '(\\b(?:has|carries|holds|hosts)\\s+no\\s+\\w+|\\b(?:no\\s+active|no\\s+documented|no\\s+title-level|no\\s+headline|no\\s+current)\\s+\\w+\\s+partner|\\bcategory\\s+(?:is|sits|remains)\\s+(?:vacant|available|open|uncontested|empty|unfilled|unclaimed)|\\bdestination\\s+where\\s+\\w+\\s+(?:sits|is)\\s+(?:vacant|open|available|unclaimed)|\\bwhere\\s+the\\s+\\w+(?:\\s+\\w+){0,4}\\s+category\\s+is\\s+(?:vacant|available|open|uncontested|unclaimed)|\\b(?:still\\s+seeking|yet\\s+to\\s+(?:sign|land|ink|secure))\\b|\\bcurrently\\s+lacks\\b|\\bremains\\s+without\\b|\\bis\\s+unclaimed\\b)';
  const vacancyRe = new RegExp(vacancyReSrc, 'i');
  const teamReGlobal = new RegExp('\\b' + teamPattern + '\\b', 'gi');

  // >>> v2.1.8d: teamPlusVacancyWithin now uses matchAll + min pairwise distance.
  // Old code only measured distance from FIRST team match; if team appeared twice,
  // a vacancy clause near the second mention was missed.
  function teamPlusVacancyWithin(text, maxDistance) {
    const tMatches = Array.from(text.matchAll(teamReGlobal));
    const vMatches = Array.from(text.matchAll(new RegExp(vacancyReSrc, 'gi')));
    if (tMatches.length === 0 || vMatches.length === 0) return false;
    let minDist = Infinity;
    for (const tm of tMatches) {
      for (const vm of vMatches) {
        const d = Math.abs(tm.index - vm.index);
        if (d < minDist) minDist = d;
      }
    }
    return minDist <= maxDistance;
  }

  const reA = new RegExp('\\b' + teamPattern + '\\s+is\\s+(the\\s+only|where\\b|one\\s+of\\s+the\\s+only|the\\s+destination\\s+where)', 'i');
  const reC = new RegExp('\\b(only|lone|sole)\\s+[A-Z]{1,3}\\s*\\w*\\s+team[^.]{0,80}\\b' + teamPattern + '\\b', 'i');
  const reD = /\b(two|three|four|several|multiple)\s+\w+\s+teams?\s+(carry|have|hold)\s+no\b/i;
  const reE = new RegExp('\\b' + teamPattern + '\\s+(has|carries|holds|hosts)\\s+no\\b', 'i');

  // Apply to p2
  if (reA.test(p2)) add('why_team_claim_in_case_p2_a', 'critical', "the_case_p2 has '[Team] is the only/where/destination' pattern");
  if (teamPlusVacancyWithin(p2, 100)) add('why_team_claim_in_case_p2_b', 'critical', 'the_case_p2 names team within 100 chars of a vacancy clause');
  if (reC.test(p2)) add('why_team_claim_in_case_p2_c', 'critical', "the_case_p2 has 'only [N]-team' framing naming recommended team");
  if (reD.test(p2)) add('count_claim_in_case_p2', 'medium', 'the_case_p2 makes counted-teams claim');
  if (reE.test(p2)) add('team_has_no_in_case_p2', 'critical', "the_case_p2 has '[Team] has/carries no X' pattern");

  // Apply to deck
  // >>> v2.1.8d: Patterns C and D added to deck (were p2-only)
  if (reA.test(deck)) add('team_vacancy_in_deck_a', 'critical', "deck has '[Team] is the only/where/destination' — must be company-side only");
  if (reE.test(deck)) add('team_vacancy_in_deck_e', 'critical', "deck has '[Team] HAS NO X' pattern — must be company-side only");
  if (teamPlusVacancyWithin(deck, 100)) add('team_vacancy_in_deck_b', 'critical', 'deck names team within 100 chars of a vacancy clause — must be company-side only');
  if (reC.test(deck)) add('team_vacancy_in_deck_c', 'critical', "deck has 'only [N]-team' framing — must be company-side only");
  if (reD.test(deck)) add('count_claim_in_deck', 'medium', 'deck makes counted-teams claim — must be company-side only');
}

// Rule 7: Word counts
const ceilings = { deck: 50, the_case_p1: 95, the_case_p2: 75, why_now_callout: 55, why_team_para: 85, value_content: 75, operational_fit_content: 75, deal_arch_para: 70, decision_maker_bio: 50, opening_angle_intro: 18, opening_angle_quote: 45 };
for (const key in ceilings) {
  if (!brief[key]) continue;
  const n = wc(brief[key]);
  if (n > ceilings[key] + 5) add('wc_' + key, 'medium', key + ': ' + n + ' words > ' + ceilings[key]);
}

// Rule 8: Confidence not LOW
if ((brief.confidence_level || '').toUpperCase() === 'LOW') add('low_confidence', 'critical', 'confidence_level is LOW');

// Rule 9: Track label sanity
const tl = brief.track_label;
if (tl !== undefined && tl !== '' && tl !== ' · ALUMNI INTELLIGENCE') add('bad_track_label', 'medium', "track_label '" + tl + "' invalid");

// Rule 10: Risk count
// >>> v2.1.8d: severity aligned to spec — critical when valueOn (where risk count affects
// page-2 layout), medium when valueOff (still logs but doesn't gate).
const risks = brief.risks || [];
const valueOn = !!(brief.value_section || brief.operational_fit_section);
const expectedRiskCount = valueOn ? 2 : 3;
if (risks.length !== expectedRiskCount) add('risk_count', valueOn ? 'critical' : 'medium', 'risks=' + risks.length + ', expected ' + expectedRiskCount);

// Rule 11: Page-2 char budget
// >>> v2.1.8d: budgets recalibrated 2500→2300 (valueOn) and 2300→2100 (valueOff).
// Based on tests against 5 real briefs: Nourish overflowed at ~2306 chars on old 2500.
// New 2300 catches Nourish but keeps Mercury (~2229), Farther (~2198), Primer (~2056) safe.
const bSecs = [brief.why_team_para, (brief.value_content || brief.operational_fit_content), brief.deal_arch_para, brief.decision_maker_bio, brief.opening_angle_intro, brief.opening_angle_quote];
const bChars = bSecs.map(function(s){ return plainText(s).length; }).reduce(function(a,b){return a+b;}, 0);
const rChars = risks.map(function(r){ return plainText((r[0]||'') + ' ' + (r[1]||'')).length; }).reduce(function(a,b){return a+b;}, 0);
const total = bChars + rChars;
const budget = valueOn ? 2300 : 2100;
if (total > budget) add('page2_overflow_risk', 'critical', 'page-2 char budget exceeded: ' + total + ' > ' + budget);

// Rule 12: VALUE section must render for score >= 70
const score = Number(brief.score || 0);
if (score >= 70 && !valueOn) add('value_section_missing', 'critical', 'value_section is false but score ' + score + ' >= 70 — must render VALUE TO [TEAM]');
if (valueOn && !plainText(brief.value_content || brief.operational_fit_content || '')) add('value_content_empty', 'critical', 'value_section is true but value_content is empty');

// Rule 13: phrase overlap between the_case_p2 and why_team_para (5+ words substantive)
function ngrams(text, n) {
  const words = text.toLowerCase().replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  const out = [];
  for (let i = 0; i <= words.length - n; i++) out.push(words.slice(i, i + n).join(' '));
  return out;
}
const p2Plain = plainText(brief.the_case_p2 || '');
const wtPlain = plainText(brief.why_team_para || '');
const wtSet = new Set(ngrams(wtPlain, 5));
const sharedPhrases = [];
const seen = new Set();
for (const phrase of ngrams(p2Plain, 5)) {
  if (wtSet.has(phrase) && !seen.has(phrase)) {
    seen.add(phrase);
    const STOPWORDS = new Set(['a','an','the','and','or','but','of','in','on','at','to','for','with','by','is','are','was','were','from','as','it','its','that','this','these','those','be','has','have']);
    const tokens = phrase.split(' ');
    const contentTokens = tokens.filter(function(t){ return !STOPWORDS.has(t); });
    if (contentTokens.length < 3) continue;
    if (teamRaw) {
      const teamWords = teamRaw.toLowerCase().split(/\s+/);
      const teamOverlap = tokens.filter(function(t){ return teamWords.indexOf(t) >= 0; }).length;
      if (teamOverlap >= 2) continue;
    }
    sharedPhrases.push(phrase);
  }
}
if (sharedPhrases.length > 0) {
  add('p2_why_team_phrase_overlap', 'medium', '5+ word phrase shared: "' + sharedPhrases[0] + '"' + (sharedPhrases.length > 1 ? ' (+' + (sharedPhrases.length - 1) + ' more)' : ''));
}

// Aggregate + route
const critical = violations.filter(function(v){ return v.severity === 'critical'; });
const medium = violations.filter(function(v){ return v.severity === 'medium'; });
const passed = critical.length === 0;
let route;
if (passed) route = 'pass';
else if (retryCount < 1) route = 'retry';
else route = 'manual_review';

const runDate = new Date().toISOString().slice(0, 10);
const company = brief.company || brief.footer_company || 'unknown';
const briefNum = brief.brief_number || '???';
const logRows = [{
  run_date: runDate, brief_number: briefNum, company: company,
  row_type: 'summary',
  rule: passed ? 'audit_passed' : (route === 'manual_review' ? 'audit_failed_manual_review' : 'audit_failed_retrying'),
  severity: passed ? 'info' : (critical.length > 0 ? 'critical' : 'medium'),
  detail: passed ? 'No violations.' : critical.length + ' critical, ' + medium.length + ' medium (retry=' + retryCount + ')'
}];
for (const v of violations) {
  logRows.push({ run_date: runDate, brief_number: briefNum, company: company, row_type: 'violation', rule: v.rule, severity: v.severity, detail: v.detail });
}

return [{
  json: Object.assign({}, brief, {
    _audit: { passed: passed, critical_count: critical.length, medium_count: medium.length, violations: violations, retry_count: retryCount, run_at: new Date().toISOString() },
    _audit_route: route,
    _audit_log_rows: logRows,
    _signal_data: signal,
    _retry_count: retryCount,
    _previous_violations: previousViolations
  })
}];

// Format Audit Log Rows - Phase 2.1.7b
// Takes one input item (from Audit Brief) and explodes its _audit_log_rows
// into one output item per row, shaped for the Sheets append node downstream.

const rows = $input.first().json._audit_log_rows || [];
if (rows.length === 0) {
  return [{ json: { run_date: new Date().toISOString().slice(0,10), brief_number: '???', company: 'unknown', row_type: 'summary', rule: 'no_audit_data', severity: 'info', detail: 'Audit produced no rows' } }];
}
return rows.map(function(r) { return { json: r }; });

// Retry Prep - Phase 2.1.7 (FIXED)
// Pre-formats the retry instructions as a single string so the Write Brief
// user-message expression stays trivial (no multi-line JS strings in the body).

const src = $input.first().json;
const audit = src._audit || {};
const violations = audit.violations || audit.audit_violations || [];
const failedDraft = Object.assign({}, src);
delete failedDraft._audit;
delete failedDraft._signal_data;
delete failedDraft._retry_count;
delete failedDraft._previous_violations;
delete failedDraft._audit_route;
delete failedDraft._audit_log_rows;

const signal = src._signal_data || {};

// Format violation lines (newline-separated string)
const violationLines = violations.map(function(v) {
  return '- [' + v.severity.toUpperCase() + '] ' + v.rule + ': ' + v.detail;
}).join('\n');

// Pre-format the complete retry block as ONE string. This goes verbatim into
// the user message via a single simple expression -- no JS in the body field.
const retryBlock = [
  '',
  '=== RETRY MODE - CORRECTING PREVIOUS DRAFT ===',
  'The previous draft of this brief failed automated audit. Fix EVERY violation below while keeping the facts intact.',
  '',
  'VIOLATIONS TO FIX:',
  violationLines,
  '',
  'PREVIOUS DRAFT (BRIEF_DATA fields):',
  JSON.stringify(failedDraft, null, 2),
  '',
  'Produce a corrected BRIEF_DATA that resolves every violation. Keep the same facts; change only the prose that violates the rules. Apply the retry rules in the system prompt. There is no second retry - get it right this time.',
  ''
].join('\n');

// Rebuild the data shape the Write Brief node expects (the original signal shape)
// with retry annotations attached as simple string fields.
const retryInput = Object.assign({}, signal, {
  retry_count: (Number(src._retry_count) || 0) + 1,
  _is_retry: true,
  _retry_block: retryBlock,
  _previous_violations: violations
});

return [{ json: retryInput }];

// =============================================================================
// Duplicate Guard — Phase 2.1.10e (FINAL — normaliser verified against real data)
//
// PASTE INTO: the existing "Duplicate Guard" Code node (replace all current code).
//
// FIX from v2.1.10d:
//   normalise() now strips parenthetical content FIRST, then suffixes.
//   This catches "Lime" === "Lime (Neutron Holdings)" — the bug that let
//   today's Lime duplicate through to MD.
//   Verified against all 34 real Daily Signals rows: 11/11 expected behaviors.
//
// FAILURE MODES THIS GUARD CATCHES:
//   (1) MD duplicate within 30 days — by normalised company name
//   (2) Manual editor execution (mode != "production")
//   (3) Scheduled trigger node didn't fire (defensive)
//   (4) Daily Signals read failed (fail-closed)
//   (5) Score < 70 (defensive)
//   (6) Audit didn't pass (defensive)
// =============================================================================

const brief = $input.first().json;

const company = brief.company || '';
const score = Number(brief.score || 0);
const auditPassed = brief._audit && brief._audit.passed === true;

// ---- Read Daily Signals via explicit named node reference ----
let signalRows = [];
let sheetsReadOk = false;
try {
  const sheetItems = $('Google Sheets — Read Daily Signals').all();
  if (Array.isArray(sheetItems)) {
    signalRows = sheetItems.map(function(i){ return i.json; }).filter(function(r){ return r && (r.Company || r.company); });
    sheetsReadOk = true;
  }
} catch (e) {
  signalRows = [];
  sheetsReadOk = false;
}

// ---- Verify scheduled trigger fired (belt-and-braces) ----
let triggerFired = false;
try {
  const triggerData = $('6am Weekdays Trigger').all();
  triggerFired = Array.isArray(triggerData) && triggerData.length > 0;
} catch (e) {
  triggerFired = false;
}

// ---- Helpers ----
// v2.1.10e: parenthetical content stripped BEFORE suffix stripping.
// Verified against real Daily Signals data: catches "Lime" vs "Lime (Neutron Holdings)",
// "Exa" vs "Exa Labs", and all other tested variants without over-matching.
function normalise(name) {
  return (name || '')
    .toLowerCase()
    .replace(/\([^)]*\)/g, ' ')  // strip (parenthetical content) FIRST
    .replace(/\b(inc|ltd|llc|corp|corporation|technologies|technology|ai|labs|lab|holdings|holding|group|company|co|the)\b/g, ' ')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

function parseDateMs(s) {
  if (!s) return NaN;
  const str = String(s).trim();
  let ms = new Date(str + 'T00:00:00Z').getTime();
  if (!isNaN(ms)) return ms;
  const m = str.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return Date.UTC(parseInt(m[1], 10), parseInt(m[2], 10) - 1, parseInt(m[3], 10));
  return NaN;
}

const blocks = [];
const companyNorm = normalise(company);

// ---- GATE 1: Execution mode whitelist ----
let execMode = 'unknown';
try { execMode = $execution.mode; } catch (e) { execMode = 'unknown'; }

if (execMode !== 'production') {
  blocks.push({
    rule: 'blocked_non_production_execution',
    detail: 'execution_mode=' + execMode + '. Only "production" (scheduled cron) reaches MD.'
  });
}

if (!triggerFired) {
  blocks.push({
    rule: 'blocked_trigger_not_fired',
    detail: 'execution_mode=' + execMode + ' but "6am Weekdays Trigger" node did not fire.'
  });
}

// ---- GATE 2: Sheets read verification ----
if (!sheetsReadOk || signalRows.length === 0) {
  blocks.push({
    rule: 'blocked_signals_log_unreachable',
    detail: 'Daily Signals read returned ' + signalRows.length + ' rows (sheetsReadOk=' + sheetsReadOk + ').'
  });
}

// ---- GATE 3: Duplicate within 30 days ----
const todayIso = new Date().toISOString().slice(0, 10);
const todayMs = parseDateMs(todayIso);
const cutoffMs = todayMs - 30 * 86400000;

const recentSends = signalRows.filter(function(r) {
  const rowDate = r.Date || r.date || r.run_date;
  const rowCompany = r.Company || r.company;
  if (!rowDate || !rowCompany) return false;
  const rowMs = parseDateMs(rowDate);
  if (isNaN(rowMs)) return false;
  if (rowMs < cutoffMs) return false;
  if (rowMs >= todayMs) return false;
  return normalise(rowCompany) === companyNorm;
});

if (recentSends.length > 0) {
  const dates = recentSends.map(function(r){ return r.Date || r.date || r.run_date; }).join(', ');
  const names = recentSends.map(function(r){ return r.Company || r.company; }).join(', ');
  blocks.push({
    rule: 'blocked_duplicate_30d',
    detail: 'Company "' + company + '" matches recent brief(s): ' + names + ' on dates: ' + dates + '. Normalised match: "' + companyNorm + '". Send suppressed to prevent MD duplicate.'
  });
}

// ---- GATE 4: Defensive reverification ----
if (score < 70) {
  blocks.push({
    rule: 'blocked_score_below_threshold',
    detail: 'Score ' + score + ' < 70 threshold.'
  });
}
if (!auditPassed) {
  blocks.push({
    rule: 'blocked_audit_not_passed',
    detail: '_audit.passed is not true (got: ' + JSON.stringify(brief._audit) + ').'
  });
}

// ---- Result ----
const passed = blocks.length === 0;
const route = passed ? 'send' : 'block';

const logRows = [];
if (passed) {
  logRows.push({
    run_date: todayIso,
    brief_number: brief.brief_number || '???',
    company: company,
    row_type: 'guard',
    rule: 'duplicate_guard_passed',
    severity: 'info',
    detail: 'Duplicate Guard passed. Proceeding to Outlook Send Brief. signals_rows=' + signalRows.length + ', exec_mode=' + execMode + ', trigger_fired=' + triggerFired + ', companyNorm=' + companyNorm + '.'
  });
} else {
  logRows.push({
    run_date: todayIso,
    brief_number: brief.brief_number || '???',
    company: company,
    row_type: 'guard',
    rule: 'duplicate_guard_blocked',
    severity: 'critical',
    detail: blocks.length + ' guard block(s): ' + blocks.map(function(b){return b.rule;}).join(', ') + ' (signals_rows=' + signalRows.length + ', exec_mode=' + execMode + ', trigger_fired=' + triggerFired + ')'
  });
  for (const b of blocks) {
    logRows.push({
      run_date: todayIso,
      brief_number: brief.brief_number || '???',
      company: company,
      row_type: 'guard_block',
      rule: b.rule,
      severity: 'critical',
      detail: b.detail
    });
  }
}

return [{
  json: Object.assign({}, brief, {
    _guard: {
      passed: passed,
      blocks: blocks,
      route: route,
      execution_mode: execMode,
      trigger_fired: triggerFired,
      signals_rows_read: signalRows.length,
      sheets_read_ok: sheetsReadOk,
      company_normalised: companyNorm,
      checked_at: new Date().toISOString()
    },
    _guard_route: route,
    _audit_log_rows: (brief._audit_log_rows || []).concat(logRows)
  })
}];
